export const concepts = [
  ['CLNG-R2-CON001', 'source file and executable', 'A .c file stores source text; GCC builds a separate executable that Windows can run.', '`gcc -std=c17 -Wall -Wextra profile.c -o profile.exe` builds before `.\\profile.exe` runs.', 'Assuming VS Code runs changed source merely because the file is open.'],
  ['CLNG-R2-CON002', 'preprocess, compile, and link', 'Headers are processed, source is translated, and required definitions are linked before a runnable file exists.', 'A declared printf call is linked with the C library implementation.', 'Calling every build failure a syntax error.'],
  ['CLNG-R2-CON003', 'main and exit status', 'Execution begins in main, whose returned integer reports success or failure to the surrounding process.', '`return 0;` reports successful completion.', 'Using output text as though it were the process exit status.'],
  ['CLNG-R2-CON004', 'diagnostic evidence', 'A warning or error gives a severity, source location, and message that should be read before editing.', 'A format warning names the expected and supplied argument types.', 'Running a program after a serious type warning instead of repairing it.'],
  ['CLNG-R2-CON005', 'typed object', 'A declared object has a type, stored value, memory location, and lifetime.', '`int weekly_minutes = 360;` creates an initialized integer object.', 'Reading an uninitialized automatic object.'],
  ['CLNG-R2-CON006', 'printf conversion', 'Each conversion specifier tells printf how to interpret the corresponding argument.', '`%d`, `%.1f`, and `%c` match int, double, and char arguments.', 'Using `%f` for an int and assuming the output will be converted safely.'],
  ['CLNG-R2-CON007', 'scanf conversion count', 'scanf returns how many requested values it converted successfully.', '`scanf("%d %d", &days, &minutes) == 2` confirms both integers exist.', 'Using objects after a failed conversion left them unchanged.'],
  ['CLNG-R2-CON008', 'address-of for input', 'The & operator gives scanf the location of an object it is allowed to write.', '`&days` points to the days object.', 'Passing days instead of &days for a numeric conversion.'],
  ['CLNG-R2-CON009', 'integer division and remainder', 'Integer operands produce a truncated integer quotient; remainder keeps what division did not consume.', '`95 / 60` is 1 and `95 % 60` is 35.', 'Storing integer division in double and expecting the lost fraction to return.'],
  ['CLNG-R2-CON010', 'explicit arithmetic conversion', 'Converting an operand before arithmetic can select floating-point calculation deliberately.', '`(double)total / count` keeps the fractional average.', 'Casting only after integer division already discarded the fraction.'],
  ['CLNG-R2-CON011', 'ordered branch', 'An if/else-if/else chain takes the first matching branch, so invalid cases belong before dependent calculations.', 'Reject zero classes held before calculating attendance percent.', 'Calculating first and validating the divisor afterward.'],
  ['CLNG-R2-CON012', 'short-circuit logic', '&& and || evaluate left to right and may skip the right side when the result is already known.', '`held > 0 && attended <= held` avoids treating the second rule as sufficient alone.', 'Replacing && with || and accepting a record that violates one required rule.'],
  ['CLNG-R2-CON013', 'boundary case', 'A boundary is the exact edge where expected behavior changes.', 'Exactly 75 percent is the first eligible attendance result.', 'Testing only a comfortable middle value.'],
  ['CLNG-R2-CON014', 'loop progress', 'A loop needs a changing value that can move its condition toward false.', 'Increment index after storing each valid score.', 'Updating a different variable and creating an endless loop.'],
  ['CLNG-R2-CON015', 'array extent and index', 'A fixed array owns a known number of elements indexed from zero through count minus one.', '`scores[count - 1]` is the last initialized score when count is positive.', 'Using index <= count or reading unused array elements.'],
  ['CLNG-R2-CON016', 'accumulator and initial state', 'A summary variable begins from an intentional state and is updated once per included value.', 'total starts at zero while minimum starts from the first valid score.', 'Starting minimum at zero when every score is positive.'],
  ['CLNG-R2-CON017', 'function contract and prototype', 'A prototype tells callers the function name, parameter types, and return type before the definition is seen.', '`double divide_values(double left, double right);` declares the call contract.', 'Calling a function through an absent or contradictory declaration.'],
  ['CLNG-R2-CON018', 'return value', 'return sends one compatible result to the caller and ends that invocation.', '`return left + right;` lets main decide how to present the result.', 'Printing in a helper when another function needs the value.'],
  ['CLNG-R2-CON019', 'pass by value', 'A C parameter receives a copy of the supplied value unless a pointer explicitly provides access to another object.', 'Changing a double parameter does not change the caller double.', 'Expecting an ordinary parameter assignment to update the caller.'],
  ['CLNG-R2-CON020', 'translation unit and linker', 'Each .c file is compiled separately, then the linker connects referenced definitions.', 'Both `main.c` and `calc.c` are named in the final GCC command.', 'Treating an undefined-reference linker message as a missing semicolon.'],
  ['CLNG-R2-CON021', 'C string and NUL terminator', 'A C string is a char sequence whose first zero byte marks the end of text.', 'A 40-byte name array can hold at most 39 visible one-byte characters plus `\\0`.', 'Filling every byte with visible characters and leaving no terminator.'],
  ['CLNG-R2-CON022', 'buffer capacity', 'Array capacity is the storage available; string length is the visible text currently stored.', '`sizeof student.name` gives the member array capacity inside the owning scope.', 'Using strlen as though it measured destination capacity.'],
  ['CLNG-R2-CON023', 'pointer and dereference', 'A pointer stores an address; dereferencing accesses the live object at that address.', '`Student *match = &students[index];` points to an array element.', 'Dereferencing NULL or an address that no longer names a live object.'],
  ['CLNG-R2-CON024', 'pointer validity and lifetime', 'A pointer is usable only while it points to a suitably aligned live object and the operation stays within that object.', 'Returning a pointer to an element in main’s still-live array is valid during main.', 'Returning the address of a local temporary after its function returns.'],
  ['CLNG-R2-CON025', 'struct record', 'A struct groups named members that together describe one record.', '`Student` groups id, name, and score for one learner.', 'Keeping related fields in unsynchronized parallel arrays.'],
  ['CLNG-R2-CON026', 'member access through a pointer', 'Use . with a struct object and -> with a pointer to a struct.', '`match->score = 84;` updates the pointed-to record.', 'Using dot on a pointer or arrow on a non-pointer object.'],
  ['CLNG-R2-CON027', 'FILE pointer and mode', 'fopen returns a FILE pointer for a requested mode or NULL when opening fails.', '`fopen(path, "r")` opens existing text for reading without truncating it.', 'Using write mode while intending only to inspect existing data.'],
  ['CLNG-R2-CON028', 'read loop and end state', 'A file-reading loop should test the read operation, then distinguish normal end-of-file from an I/O error.', '`while (fgets(line, sizeof line, file) != NULL)` processes successful reads.', 'Using `while (!feof(file))` and processing stale data once more.'],
  ['CLNG-R2-CON029', 'record parse contract', 'A persisted line is valid only when every required field converts, ranges pass, and no forbidden delimiter remains.', '`id|minutes|subject` is accepted only after all three fields pass.', 'Accepting a partially parsed line and silently filling missing data.'],
  ['CLNG-R2-CON030', 'narrow file recovery', 'A missing first-run file may mean empty state, while malformed or unreadable existing data must stop without replacement.', 'ENOENT starts an empty log; a malformed line preserves the original file.', 'Treating every fopen failure as an empty file and overwriting evidence.'],
  ['CLNG-R2-CON031', 'debugger evidence', 'A breakpoint pauses a reproducible case so actual indexes, counts, values, and pointed-to objects can be inspected.', 'Pause before assigning next_id and compare highest_id with the proposed value.', 'Changing several lines before reproducing one stable failure.'],
  ['CLNG-R2-CON032', 'check harness', 'A small check compares one actual result with its expected contract and reports a visible pass or failure.', '`check_int("next id", 3, actual)` records the rule being protected.', 'Changing the expected result merely to make a failing check pass.'],
  ['CLNG-R2-CON033', 'argc and argv contract', 'argc counts command-line tokens and argv stores their text; length must be checked before indexing.', '`labtrack.exe complete 3` supplies a command and an ID token.', 'Reading argv[2] before confirming that it exists.'],
  ['CLNG-R2-CON034', 'reproducible C repository', 'A repository is reviewable when source, checks, sample data, and README reproduce the build without generated or private files.', 'README records the exact C17 compile, run, and check commands.', 'Publishing .exe files, .vscode machine paths, secrets, or personal records.'],
].map(([id, term, simpleMeaning, example, commonMistake]) => ({ id, term, simpleMeaning, example, commonMistake }));

const build = ({ week, title, outcome, brief, competencyIds, priorKnowledgeCompetencyIds, conceptRefs, whyItMatters, steps, criteria, hints, templates, stretch, sessions, finishedResult }) => {
  const prefix = `CLNG-R2-B-W${String(week).padStart(2, '0')}-01`;
  return {
    id: prefix, title, required: true, outcome, competencyIds,
    estimatedMinutes: sessions.reduce((sum, session) => sum + session.minutes, 0), brief,
    steps: steps.map((text, index) => ({ id: `${prefix}-S${String(index + 1).padStart(2, '0')}`, text })),
    acceptanceCriteria: criteria.map((text, index) => ({ id: `${prefix}-A${String(index + 1).padStart(2, '0')}`, text })),
    hints,
    templates: templates.map((item, index) => ({ id: `${prefix}-T${String(index + 1).padStart(2, '0')}`, ...item })),
    stretch,
    learnerGuide: {
      summary: brief, whyItMatters, priorKnowledgeCompetencyIds, finishedResult, conceptRefs,
      sessions: sessions.map((session, index) => ({ id: `${prefix}-SESSION-${String(index + 1).padStart(2, '0')}`, title: session.title, estimatedMinutes: session.minutes, stepIds: session.stepIndexes.map((stepIndex) => `${prefix}-S${String(stepIndex).padStart(2, '0')}`) })),
    },
  };
};

